export default"\n.el-radio__input.is-checked + .el-radio__label {\n  color: var(--primary-active-bg) !important;\n}\n\n#container_meta_sidebar #sidebar_top #sidebar_top_apps_container img,\n#container_meta_sidebar #menus_search_container button,\n#sidebar_top_apps_button,\n#sidebar_about_button {\n  transform: scale(0.9);\n}\n\n/* 通过滤镜修改原本白底的图标 */\n#container_meta_header_logo,\n#container_meta_sidebar #sidebar_top #sidebar_top_apps_container img,\n#container_meta_sidebar #menus_search_container button,\n#container_meta_sidebar #sidebar_top #sidebar_top_apps_container img,\n#sidebar_top_apps > button,\n#container_meta_sidebar > button,\n#menu_meta_siderbar .menuList .el-submenu__title .el-image img,\n#menu_meta_siderbar .applicationName div.line,\n#container_meta_header_left #container_meta_header_menu_shrink,\n#menu_meta_siderbar .el-menu-item img {\n  filter: invert(45%) sepia(10%) saturate(1400%) hue-rotate(90deg) brightness(90%) contrast(100%);\n}\n\n.el-input-group__append button.el-button:not(.is-disabled) > span,\n.menus_search_container .el-icon-search,\n#container_meta_header_right button,\n.dropdown-001 .el-button--text {\n  color: var(--primary-active-bg) !important;\n}\n\n#container_meta_sidebar,\n#menu_meta_siderbar {\n  border-right: 1px solid #e1e7ec;\n}\n\n#container_meta_header_top {\n  border-bottom: 1px solid #e1e7ec;\n}\n\n#tabs_meta_main_content_labels .el-tabs__nav-scroll {\n  background: rgb(255, 255, 255);\n}\n#tabs_meta_main_content_labels .el-tabs__nav-scroll .el-tabs__nav.is-top div[role='tab'] {\n  border-radius: 8px;\n  margin-right: 10px;\n  background: #f2f2f2 !important;\n  transition: all 0.3s ease;\n}\n#tabs_meta_main_content_labels .el-tabs__nav-scroll .el-tabs__nav .is-active[role='tab'] {\n  border-radius: 8px 8px 0px 0px !important;\n}\n#dropdown-tree-table_box .textInputDiv,\n.tech-tabs .el-tabs__active-bar {\n  background: var(--primary-active-bg) !important;\n}\n#tabs_meta_main_content_labels .el-tabs__header.is-top {\n  height: 46px !important;\n  background: #fff !important;\n  display: flex;\n  align-items: center;\n  padding: 10px;\n}\n\n.el-tag {\n  color: var(--primary-active-bg);\n  background-color: var(--sidebar-active-bg);\n  border-color: var(--sidebar-about-title-color);\n}\n\n/* loading加载图标 */\n.el-loading-spinner .path {\n  stroke: var(--primary-active-bg);\n}\n\n.el-tree--highlight-current .el-tree-node.is-current > .el-tree-node__content {\n  background-color: var(--sidebar-active-bg);\n}\n.el-input.is-active .el-input__inner,\n.el-input__inner:focus {\n  border-color: var(--primary-active-bg);\n}\n";